import{_ as p,a0 as d,w as a,s as e,I as o,x as n,a1 as i,A as u,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"在UEFI模式下安裝Ubuntu 14.04與Windows 8/8.1雙啓動 | LCTT x X-CMD","titleTemplate":false,"description":"在UEFI模式下安裝Ubuntu 14.04與Windows 8/8.1雙啓動 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在UEFI模式下安裝Ubuntu 14.04與Windows 8/8.1雙啓動 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在UEFI模式下安裝Ubuntu 14.04與Windows 8/8.1雙啓動 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/Guide To Install Ubuntu 14.04 In Dual Boot Mode With Windows 8 Or 8.1 UEFI","title":"在UEFI模式下安裝Ubuntu 14.04與Windows 8/8.1雙啓動","tag":"201406","desc":""},"relativePath":"201406/Guide To Install Ubuntu 14.04 In Dual Boot Mode With Windows 8 Or 8.1 UEFI.md","filePath":"[post].md"}'),r={name:"201406/Guide To Install Ubuntu 14.04 In Dual Boot Mode With Windows 8 Or 8.1 UEFI.md"};function w(b,t,U,m,f,g){const s=d("Link");return a(),e("div",null,[t[25]||(t[25]=o("h1",{id:"在uefi模式下安裝ubuntu-14-04與windows-8-8-1雙啓動",tabindex:"-1"},[n("在UEFI模式下安裝Ubuntu 14.04與Windows 8/8.1雙啓動 "),o("a",{class:"header-anchor",href:"#在uefi模式下安裝ubuntu-14-04與windows-8-8-1雙啓動","aria-label":"Permalink to “在UEFI模式下安裝Ubuntu 14.04與Windows 8/8.1雙啓動”"},"​")],-1)),t[26]||(t[26]=o("p",null,[o("img",{src:"http://itsfoss.com/wp-content/uploads/2014/05/Dual_Boot_Windows8_Ubuntu_1404.jpeg",alt:""})],-1)),o("p",null,[t[1]||(t[1]=n("之前我已經寫過關於",-1)),i(s,{href:"http://itsfoss.com/install-ubuntu-dual-boot-mode-windows/"},{default:u(()=>[...t[0]||(t[0]=[n("如何安裝Ubuntu Linux和Windows 7",-1)])]),_:1}),t[2]||(t[2]=n("以及8的雙啓動，但是那些教程不包含那些預裝Windows 8的系統。那些較新的預裝了Windows 8或Windows 8.1的系統使用了UEFI來替代BIOS。這使得安裝雙啓動變得和之前的常規方法有點不同。在這個教程中，我們將看到",-1)),t[3]||(t[3]=o("strong",null,"如何在UEFI模式下安裝Ubuntu 14.04與Windows 8/8.1雙啓動",-1)),t[4]||(t[4]=n("。",-1))]),t[27]||(t[27]=o("p",null,"這個教程是在一台新買的戴爾靈越 7437（酷睿i7第四代處理器， 256GB SSD，8GB內存以及內置1GB(共享內存) Intel顯卡）上演示的。為了使你能夠成功安裝UEFI下Linux和Windows 8的雙啓動，我會提到你需要做的所有步驟。如果你已經完成這些步驟中的部分步驟，直接跳到下一步。如果你有個全新的系統，那就更好了。",-1)),t[28]||(t[28]=o("p",null,"在這裏提到的這些步驟也適用於其它基於Ubuntu的Linux發行版，如Linux Mint，Elementary OS等等。不多説，讓我們來看看如何在啓用了UEFI安全啓動的Windows 8系統上雙啓動Linux。",-1)),t[29]||(t[29]=o("h3",{id:"讓-ubuntu-14-04-和-windows-8-雙啓動",tabindex:"-1"},[n("讓 Ubuntu 14.04 和 Windows 8 雙啓動： "),o("a",{class:"header-anchor",href:"#讓-ubuntu-14-04-和-windows-8-雙啓動","aria-label":"Permalink to “讓 Ubuntu 14.04 和 Windows 8 雙啓動：”"},"​")],-1)),t[30]||(t[30]=o("p",null,"要在一個UEFI系統上安裝Ubuntu有多方面的前提條件。讓我們來一個一個看：",-1)),t[31]||(t[31]=o("h4",{id:"第一步-做個備份-可選",tabindex:"-1"},[n("第一步：做個備份 [可選] "),o("a",{class:"header-anchor",href:"#第一步-做個備份-可選","aria-label":"Permalink to “第一步：做個備份 [可選]”"},"​")],-1)),o("p",null,[t[6]||(t[6]=n("做個備份總是個不錯的選擇，防止你把系統弄糟了。網上有眾多文章教你如何備份系統。你可以參照",-1)),i(s,{href:"http://www.makeuseof.com/tag/6-safest-ways-to-backup-restore-your-files-in-windows-7-8/"},{default:u(()=>[...t[5]||(t[5]=[n("這個教程",-1)])]),_:1}),t[7]||(t[7]=n("。",-1))]),t[32]||(t[32]=o("h4",{id:"第二步-創建一個ubuntu的usb啓動盤-光盤啓動盤",tabindex:"-1"},[n("第二步：創建一個Ubuntu的USB啓動盤/光盤啓動盤 "),o("a",{class:"header-anchor",href:"#第二步-創建一個ubuntu的usb啓動盤-光盤啓動盤","aria-label":"Permalink to “第二步：創建一個Ubuntu的USB啓動盤/光盤啓動盤”"},"​")],-1)),o("p",null,[t[9]||(t[9]=n("你需要做的下一件事是創建一個USB啓動盤或光盤啓動盤。我推薦在Windows下使用",-1)),i(s,{href:"http://www.pendrivelinux.com/universal-usb-installer-easy-as-1-2-3/"},{default:u(()=>[...t[8]||(t[8]=[n("Universal USB Installer",-1)])]),_:1}),t[10]||(t[10]=n("創建一個Linux OS的USB啓動盤。",-1))]),t[33]||(t[33]=l('<h4 id="第三步-為ubuntu劃分一塊安裝分區" tabindex="-1">第三步：為Ubuntu劃分一塊安裝分區 <a class="header-anchor" href="#第三步-為ubuntu劃分一塊安裝分區" aria-label="Permalink to “第三步：為Ubuntu劃分一塊安裝分區”">​</a></h4><p>假設你有一個全新的系統，我們要做的第一件事是創建一個分區來安裝Linux。我係統中的256GB磁盤出廠時就有若干個分區，但主要是用來備份及其它目的的。主分區是安裝了Windows 8.1的C盤，約有220GB。</p><p>如果你也像這樣只有一個分區，你需要從中分割出一些空間給Linux。如果你有若干空間大小足夠的分區，可以使用它們中除C盤外的任意盤，因為安裝時會抹掉其中的數據。</p><p>要在Windows 8中創建分區，需要使用磁盤管理工具。你可以通過在控制面板中搜索‘磁盤’找到磁盤管理工具。</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/disk_partition.jpeg" alt=""></p><p>在磁盤管理工具中，右鍵點擊你想劃分並縮小的卷。在我的演示中，我選擇C盤的捲進行縮小，劃分出未分配空間：</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/disk_partition_Windows8.jpeg" alt=""></p><p>縮小後出現的未分配空間就放在那裏好了，不用對其分區和格式化。我們會在安裝Ubuntu時用到它。</p><h4 id="第四步-在windows中禁用快速啓動-可選" tabindex="-1">第四步：在Windows中禁用快速啓動 [可選] <a class="header-anchor" href="#第四步-在windows中禁用快速啓動-可選" aria-label="Permalink to “第四步：在Windows中禁用快速啓動 [可選]”">​</a></h4><p>為了實現快速啓動，Windows 8引進了叫做“快速啓動”的新特性。儘管不是強制要求，最好還是將其禁用。</p><p>打開<strong>控制面板 &gt; 硬件與聲音 &gt; 電源選項 &gt; 選擇電源按鈕的功能 &gt; 更改當前不可用的設置</strong>，取消選中<strong>啓用快速啓動（推薦）</strong>。</p><h4 id="第五步-禁用windows-8-and-8-1的安全啓動-secure-boot" tabindex="-1">第五步：禁用Windows 8 and 8.1的安全啓動（secure boot） <a class="header-anchor" href="#第五步-禁用windows-8-and-8-1的安全啓動-secure-boot" aria-label="Permalink to “第五步：禁用Windows 8 and 8.1的安全啓動（secure boot）”">​</a></h4><p>這是最重要的步驟。Windows 8新的安全啓動（secure boot）原本是針對rootkit病毒的安全特性，但它也阻止了Windows和Linux的雙啓動。為了實現Windows和Linux的雙啓動，我們必須在UEFI中禁用安全啓動（secure boot）。</p>',13)),o("p",null,[t[12]||(t[12]=n("可以參見：",-1)),i(s,{href:"http://linux.cn/article-3061-1.html"},{default:u(()=>[...t[11]||(t[11]=[n("如何在 Win8 上禁用 UEFI 安全引導以安裝Linux",-1)])]),_:1}),t[13]||(t[13]=n("。",-1))]),t[34]||(t[34]=l('<h4 id="第六步-安裝ubuntu-與windows-8共存" tabindex="-1">第六步：安裝Ubuntu，與Windows 8共存 <a class="header-anchor" href="#第六步-安裝ubuntu-與windows-8共存" aria-label="Permalink to “第六步：安裝Ubuntu，與Windows 8共存”">​</a></h4><p>一旦你禁用了安全啓動（secure boot），那就是時候安裝Ubuntu了。我希望你像第二步中提到的一樣創建了一個USB啓動盤。插入U盤，然後從U盤啓動系統。</p><p>要從USB啓動，需要在Windows中選擇從USB啓動的選項。從電腦設置（像UEFI）中選擇選項或在點擊“重新啓動”的時候按住Shift鍵。</p><p>當你用USB啓動盤啓動後，你會看到試用（try）或者安裝（install）Ubuntu的選擇，這裏要點擊“安裝”。另外在屏幕上不多的設置選項裏面，你可以選擇你用的語言。接下來是關於硬盤空間，電源和網絡連接等等的一些檢查。只需點擊<strong>繼續</strong>。</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Installing_Windows8_Ubuntu.jpeg" alt=""></p><p>安裝窗口中你需要注意的是<strong>安裝類型（Installation Type）</strong>。選擇這裏的<strong>其它選項（Something else）</strong>：</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Installing_Windows8_Ubuntu_1.jpeg" alt=""></p><p>還記得我們事先劃分的未分配空間嗎？我們將用它來創建根分區（ / ），交換空間（Swap）以及家目錄（Home）。選擇空閒（free space）然後點擊加號（+）。</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Installing_Windows8_Ubuntu_2.jpeg" alt=""></p><p>它會給你提供創建Linux分區的選項。我們正在創建根分區 /。10到20GB空間就足夠了。選擇大小（Size），然後選擇Ext 4作為文件系統以及 /（意思是根）作為掛載點（Mount point）。</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Installing_Windows8_Ubuntu_3.png" alt=""></p><p>點擊確定會回到分區界面。下一步我們創建交換空間（Swap）。像之前一樣，再次點擊加號（+）。這次我們選擇作為交換空間（Swap area）。建議的交換空間大小是物理內存的兩倍。</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Installing_Windows8_Ubuntu_4.png" alt=""></p><p>以同樣的方式創建家目錄（Home）。給它分配最大的空間（實際上是給它分配剩餘的所有空間），因為這是你會用來存儲音樂，圖片以及下載的文件的位置。</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Installing_Windows8_Ubuntu_5.png" alt=""></p><p>分配好了根分區（ / ），交換空間（Swap）和家目錄（Home）之後，點擊<strong>現在安裝（Install Now）</strong>：</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Installing_Windows8_Ubuntu_6.jpeg" alt=""></p><p>好了，你現在基本上以及贏得了這場戰役了~露出勝利的微笑吧~接下來你會被要求設置用户名密碼等等。基本上你現在只需點擊下一步。</p><p>一旦安裝完成，重新啓動電腦，你應該會看到紫色的grub歡迎界面。盡情享受Ubuntu和Windows 8的雙啓動模式吧。（譯註：對於可能出現grub系統選擇中沒有Windows 8選項或是無法正常啓動的情況，可搜索Boot Repair工具的使用）</p><p>我希望這份指南能夠幫你實現Ubuntu和Windows 8的UEFI模式雙啓動。雖然這篇文章是為Ubuntu寫的，它對其它的Linux OS應該也有所幫助。歡迎提出任何問題與建議。</p><hr>',21)),o("p",null,[t[15]||(t[15]=n("via: ",-1)),i(s,{href:"http://itsfoss.com/install-ubuntu-1404-dual-boot-mode-windows-8-81-uefi/"},{default:u(()=>[...t[14]||(t[14]=[n("http://itsfoss.com/install-ubuntu-1404-dual-boot-mode-windows-8-81-uefi/",-1)])]),_:1})]),o("p",null,[t[18]||(t[18]=n("譯者：",-1)),i(s,{href:"https://github.com/alim0x"},{default:u(()=>[...t[16]||(t[16]=[n("alim0x",-1)])]),_:1}),t[19]||(t[19]=n(" 校對：",-1)),i(s,{href:"https://github.com/wxy"},{default:u(()=>[...t[17]||(t[17]=[n("wxy",-1)])]),_:1})]),o("p",null,[t[22]||(t[22]=n("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[20]||(t[20]=[n("LCTT",-1)])]),_:1}),t[23]||(t[23]=n(" 原創翻譯，",-1)),i(s,{href:"http://linux.cn/"},{default:u(()=>[...t[21]||(t[21]=[n("Linux中國",-1)])]),_:1}),t[24]||(t[24]=n(" 榮譽推出",-1))])])}const T=p(r,[["render",w]]);export{x as __pageData,T as default};
